html:
{%- set company = frappe.db.get_value("Project", doc.project, "company") if doc.project else None -%}
{%- set tender = frappe.db.get_value("BF Tender", doc.tender, ["tender_name"], as_dict=True) if doc.tender else None -%}
{%- set bills = [] -%}
{%- set bill_totals = {} -%}
{%- for row in doc.items -%}
	{%- set b = row.bill or _("General Items") -%}
	{%- if b not in bills %}{% set _ = bills.append(b) %}{% endif -%}
	{%- set _ = bill_totals.update({b: (bill_totals.get(b) or 0) + (row.amount or 0)}) -%}
{%- endfor -%}
<style>
	.boq { font-family: "Helvetica Neue", Arial, sans-serif; font-size: 10.5px; color: #111; }
	.boq h1 { font-size: 17px; text-align: center; margin: 0 0 2px; letter-spacing: 1px; }
	.boq .sub { text-align: center; color: #444; margin-bottom: 10px; }
	.boq table { width: 100%; border-collapse: collapse; }
	.boq th, .boq td { border: 1px solid #9ca3af; padding: 3px 5px; vertical-align: top; }
	.boq th { background: #e5e7eb; font-weight: 700; text-align: left; }
	.boq .num { text-align: right; white-space: nowrap; }
	.boq .bill-row td { background: #f3f4f6; font-weight: 700; }
	.boq .total-row td { font-weight: 700; background: #f9fafb; }
	.boq .grand td { font-weight: 800; font-size: 12px; background: #e5e7eb; }
	.boq .meta td { border: none; padding: 1px 4px; }
	.boq .sign td { border: none; padding-top: 28px; }
	.boq .summary-title { page-break-before: always; }
</style>
<div class="boq">
	<h1>{{ _("BILL OF QUANTITIES") }}</h1>
	<div class="sub">{{ (tender.tender_name if tender else "") or doc.project }}</div>
	<table class="meta" style="margin-bottom:8px">
		<tr><td><b>{{ _("Contractor") }}:</b> {{ company or "" }}</td><td class="num"><b>{{ _("BOQ No.") }}:</b> {{ doc.name }}</td></tr>
		<tr><td><b>{{ _("Project") }}:</b> {{ frappe.db.get_value("Project", doc.project, "project_name") or doc.project }}</td><td class="num"><b>{{ _("Date") }}:</b> {{ frappe.utils.formatdate(doc.date) if doc.date else "" }}</td></tr>
		{% if doc.tender %}<tr><td><b>{{ _("Tender") }}:</b> {{ doc.tender }}</td><td></td></tr>{% endif %}
	</table>
	<table>
		<thead><tr>
			<th style="width:9%">{{ _("Item No") }}</th><th>{{ _("Description") }}</th><th style="width:7%">{{ _("Unit") }}</th>
			<th style="width:9%" class="num">{{ _("Qty") }}</th><th style="width:13%" class="num">{{ _("Rate") }}</th><th style="width:15%" class="num">{{ _("Amount") }}</th>
		</tr></thead>
		<tbody>
		{%- for b in bills %}
			<tr class="bill-row"><td colspan="6">{{ b }}</td></tr>
			{%- for row in doc.items if (row.bill or _("General Items")) == b %}
			<tr>
				<td>{{ row.item_no or "" }}</td>
				<td>{{ row.description or "" }}</td>
				<td>{{ row.uom or "" }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.quantity, precision=2) }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.unit_rate, precision=2) }}</td>
				<td class="num">{{ frappe.utils.fmt_money(row.amount, precision=2) }}</td>
			</tr>
			{%- endfor %}
			<tr class="total-row"><td colspan="5">{{ _("Total for {0} carried to Summary").format(b) }}</td><td class="num">{{ frappe.utils.fmt_money(bill_totals[b], precision=2) }}</td></tr>
		{%- endfor %}
		</tbody>
	</table>

	<h1 class="summary-title">{{ _("SUMMARY") }}</h1>
	<div class="sub">{{ (tender.tender_name if tender else "") or doc.project }}</div>
	<table>
		<thead><tr><th style="width:8%">#</th><th>{{ _("Bill") }}</th><th style="width:22%" class="num">{{ _("Amount") }}</th></tr></thead>
		<tbody>
		{%- for b in bills %}
			<tr><td>{{ loop.index }}</td><td>{{ b }}</td><td class="num">{{ frappe.utils.fmt_money(bill_totals[b], precision=2) }}</td></tr>
		{%- endfor %}
		{%- if doc.summary_lines %}
		{%- for line in doc.summary_lines %}
			<tr{% if line.line_type == "Subtotal" or loop.first %} class="total-row"{% endif %}><td></td><td>{{ line.label }}</td><td class="num">{% if line.line_type == "Less" %}({{ frappe.utils.fmt_money(line.amount, precision=2) }}){% else %}{{ frappe.utils.fmt_money(line.amount, precision=2) }}{% endif %}</td></tr>
		{%- endfor %}
			<tr class="grand"><td colspan="2">{{ _("BID PRICE (carried to the Form of Tender)") }}</td><td class="num">{{ frappe.utils.fmt_money(doc.bid_price, precision=2) }}</td></tr>
		{%- else %}
			<tr class="grand"><td colspan="2">{{ _("TOTAL (carried to Form of Tender)") }}</td><td class="num">{{ frappe.utils.fmt_money(doc.total_amount, precision=2) }}</td></tr>
		{%- endif %}
		</tbody>
	</table>
	<table class="sign">
		<tr>
			<td>{{ _("Signed for and on behalf of") }}: ______________________________</td>
			<td>{{ _("Name & Position") }}: ______________________________</td>
		</tr>
		<tr>
			<td>{{ _("Date") }}: ______________________</td>
			<td>{{ _("Company Stamp") }}:</td>
		</tr>
	</table>
</div>
